namespace qqworld_collector\module\remote_publish; use qqworld_collector\lib; class remote_publish extends lib { var $guid; var $client = null; public function __construct() { add_filter( 'qqworld-collector-remote-publish-to-'.$this->guid, array($this, 'remote_publish'), 10, 4 ); add_action( 'qqwold-collector-remote-publish-refresh-archives-'.$this->guid, array($this, 'cron_refresh_archives'), 10, 4 ); add_action( 'qqworld-collector-remote-publish-do-publishing-singular-'.$this->guid, array($this, 'do_publishing_singular'), 10, 3 ); add_action( 'qqworld-collector-remote-publish-do-publishing-taxonomy-'.$this->guid, array($this, 'do_publishing_taxonomy'), 10, 3 ); add_action( 'qqworld-collector-remote-publish-do-publishing-homepage-'.$this->guid, array($this, 'do_publishing_homepage') ); add_action( 'qqworld-collector-remote-publish-do-publishing-sitemap-'.$this->guid, array($this, 'do_publishing_sitemap'), 10, 3 ); } public function get_client($args) {} public function handle($content, $destination_path) { sleep($this->options->qc_static_cache_stress); $content = $this->minify_html($content); do_action( 'qqworld-collector-remote-publish-handle', $content, $destination_path, $this ); } public function upload($source_path) { $destination_path = '/' . str_replace(ABSPATH, '', $source_path); $destination_path = str_replace(DIRECTORY_SEPARATOR, '/', $destination_path); $this->client->upload($destination_path, $source_path); } public function upload_minify_js_css($content, $host) { $preg = preg_match('/<script id="combined-scripts" src="(.*?)"><\/script>/', $content, $match); if ($preg) { $string = file_get_contents($match[1]); $destination_path = str_replace($host, '', $match[1]); $this->handle($string, $destination_path); } $preg = preg_match('/<link id="combined-styles".*?href="(.*?)">/', $content, $match); if ($preg) { $string = file_get_contents($match[1]); $destination_path = str_replace($host, '', $match[1]); $this->handle($string, $destination_path); } } public function publish_singular($args, $post_id, $post = null) { extract($args); if (!$post) $post = get_post($post_id, ARRAY_A); if (!$this->client) $this->client = $this->get_client($args); $url = urldecode(get_permalink($post_id)); $destination_path = str_replace(home_url(), '', $url); if (!preg_match('/\.html$/i', $destination_path)) { $destination_path = preg_replace('/\/*$/i', '', $destination_path); $destination_path .= '/index.html'; } $response = wp_remote_get($url, array('sslverify' => false)); $content = wp_remote_retrieve_body($response); $content = str_replace(home_url(), $host, $content); $this->upload_minify_js_css($content, $host); $this->handle($content, $destination_path); $urls = array($host . $destination_path); do_action( 'qqworld-collector-submit-urls-to-baidu', $urls, $post['post_type'], $post_id ); do_action( 'qqworld-collector-submit-urls-to-shenma', $urls, $post['post_type'], $post_id ); do_action( 'qqworld-collector-submit-urls-to-bing', $urls, $post['post_type'], $post_id ); $pages = explode('<!--nextpage-->', $post['post_content']); if (count($pages) > 1) { for ($i=2; $i<=count($pages); $i++) { $paged_url = preg_replace('/\/*$/i', '', $url) . '/' . $i; $destination_path = str_replace(home_url(), '', $paged_url); $destination_path = preg_replace('/\/*$/i', '', $destination_path); $destination_path .= '/index.html'; $content = file_get_contents($paged_url); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); } } $attachments = get_attached_media( '', $post_id ); if (!empty($attachments)) { foreach ($attachments as $attachment) { $post_meta = get_post_meta($attachment->ID); $fullsize_path = get_attached_file($attachment->ID); $dirname = dirname($fullsize_path); $this->upload($fullsize_path); if (preg_match('/^image\//i', $attachment->post_mime_type)) { $metadata = unserialize($post_meta['_wp_attachment_metadata'][0]); if (isset($metadata['sizes'])) foreach ($metadata['sizes'] as $size_name => $size ) { $source_path = $dirname . DIRECTORY_SEPARATOR . $size['file']; $this->upload($source_path); } } } } return true; } public function publish_archive($args, $taxonomy, $term) { extract($args); if (!$this->client) $this->client = $this->get_client($args); $url = urldecode(get_term_link($term->term_id, $taxonomy)); $base_path = str_replace(home_url(), '', $url ); $destination_path = $base_path . '/index.html'; $content = file_get_contents($url); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); if ($term->count) { $posts_per_page = get_option( 'posts_per_page' ); if ($term->count > $posts_per_page) { $pages = $term->count / $posts_per_page; $pages = is_int($pages) ? $pages : intval($pages) + 1; for ($page=2; $page<=$pages; $page++) { $destination_path = $base_path . '/page/'.$page.'/index.html'; $content = file_get_contents($url . '/page/' . $page); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); } } } } public function remote_publish($result, $post, $args, $post_id) { $result = $this->publish_singular($args, $post_id, $post); $ids = get_option( 'qqworld-collector-remote-publish-to-'.$this->guid.'-ids', array() ); $key = base64_encode(json_encode($args, JSON_INVALID_UTF8_IGNORE)); if (!isset($ids[$key])) $ids[$key] = array(); $ids[$key][] = $post_id; $ids[$key] = array_flip(array_flip($ids[$key])); update_option( 'qqworld-collector-remote-publish-to-'.$this->guid.'-ids', $ids ); if ( wp_next_scheduled( 'qqwold-collector-remote-publish-refresh-archives', array($this->guid) ) ) { wp_clear_scheduled_hook( 'qqwold-collector-remote-publish-refresh-archives', array($this->guid) ); } wp_schedule_single_event( time() + 360, 'qqwold-collector-remote-publish-refresh-archives', array($this->guid) ); return $result; } public function cron_refresh_archives() { set_time_limit($this->options->qc_stress_timeout); $ids = get_option( 'qqworld-collector-remote-publish-to-'.$this->guid.'-ids', array() ); if (!$ids) return; foreach ($ids as $args => $post_ids) { $args = json_decode(base64_decode($args), true); extract($args); if (!$this->client) $this->client = $this->get_client($args); $destination_path = '/index.html'; $content = file_get_contents(home_url()); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); $post_ids = array_flip(array_flip($post_ids)); if ($post_ids) { $terms_cache = array(); foreach ($post_ids as $post_id) { $post = get_post($post_id); $taxonomies = get_object_taxonomies( $post->post_type ); if (!empty($taxonomies)) { foreach ($taxonomies as $taxonomy) { $terms = wp_get_post_terms($post_id, $taxonomy); if (!empty($terms)) { if (!isset($terms_cache[$taxonomy])) $terms_cache[$taxonomy] = array(); foreach ($terms as $term) { if (!in_array($term->term_id, array_keys($terms_cache[$taxonomy]))) { $terms_cache[$taxonomy][$term->term_id] = $term; } } } } } } if ($terms_cache) { $posts_per_page = get_option( 'posts_per_page' ); foreach ($terms_cache as $taxonomy => $terms) { foreach ($terms as $term) { $this->publish_archive($args, $taxonomy, $term); } } } } } update_option( 'qqworld-collector-remote-publish-to-'.$this->guid.'-ids', array() ); } public function do_publishing_singular($args, $post, $guid) { $postdata = $post; if (isset($postdata['terms']) && !empty($postdata['terms'])) { $terms = $postdata['terms']; $postdata['tax_query'] = array( 'relation' => 'OR' ); foreach ($terms as $taxonomy => $term_ids) { $postdata['tax_query'][] = array( 'taxonomy' => $taxonomy, 'terms' => $term_ids, 'field' => 'id' ); } } if (isset($postdata['post_date']['after']) && $postdata['post_date']['after']) { if (!isset($postdata['date_query'])) $postdata['date_query'] = array('inclusive' => true); $datedata = explode('-', $postdata['post_date']['after']); $postdata['date_query']['after'] = array( 'year' => $datedata[0], 'month' => $datedata[1], 'day' => $datedata[2] ); } if (isset($postdata['post_date']['before']) && $postdata['post_date']['before']) { if (!isset($postdata['date_query'])) $postdata['date_query'] = array('inclusive' => true); $datedata = explode('-', $postdata['post_date']['before']); $postdata['date_query']['before'] = array( 'year' => $datedata[0], 'month' => $datedata[1], 'day' => $datedata[2] ); } unset($postdata['post_date']); $id_from = $postdata['id_from']; $id_to = $postdata['id_to']; $id_from = $id_from=='0' ? 1 : $id_from; $id_to = $id_to=='0' ? 1 : $id_to; $post__in = array(); if (!empty($id_from) && is_numeric($id_from) && empty($id_to)) { $post__in[] = $id_from; } elseif (empty($id_from) && !empty($id_to) && is_numeric($id_to)) { $post__in[] = $id_to; } elseif (!empty($id_from) && is_numeric($id_from) && !empty($id_to) && is_numeric($id_to)) { if ($id_from == $id_to) $post__in[] = $id_from; elseif ($id_from < $id_to) for ($s=$id_from; $s<=$id_to; $s++) $post__in[]=$s; elseif($id_from > $id_to) for ($s=$id_from; $s>=$id_to; $s--) $post__in[]=$s; } $postdata['post__in'] = $post__in; if (!$postdata['force-scan']) { $exclude = get_option('qqworld-collector-remote-publish-refreshing-singular-exclude-'.$guid, array()); $exclude = $exclude ? $exclude : array(); if (!empty($exclude)) $postdata['post__not_in'] = $exclude; } $postdata['posts_per_page'] = 100; for ($paged=0; $paged<1000; $paged++) { $postdata['offset'] = $postdata['posts_per_page']*$paged; $posts = get_posts($postdata); if (!empty($posts)) { foreach ($posts as $post) { $post = (array) $post; $this->publish_singular($args, $post['ID'], $post); if (!$postdata['force-scan']) $exclude[] = $post['ID']; } if (!$postdata['force-scan']) { $exclude = array_flip(array_flip($exclude)); update_option('qqworld-collector-remote-publish-refreshing-singular-exclude-'.$guid, $exclude); } } else { break; } } } public function do_publishing_taxonomy($args, $post, $guid) { $postdata = $post; if (isset($postdata['terms']) && !empty($postdata['terms'])) { $postdata['include'] = current($postdata['terms']); } $id_from = $postdata['id_from']; $id_to = $postdata['id_to']; $id_from = $id_from=='0' ? 1 : $id_from; $id_to = $id_to=='0' ? 1 : $id_to; $include = array(); if (!empty($id_from) && is_numeric($id_from) && empty($id_to)) { $include[] = $id_from; } elseif (empty($id_from) && !empty($id_to) && is_numeric($id_to)) { $include[] = $id_to; } elseif (!empty($id_from) && is_numeric($id_from) && !empty($id_to) && is_numeric($id_to)) { if ($id_from == $id_to) $include[] = $id_from; elseif ($id_from < $id_to) for ($s=$id_from; $s<=$id_to; $s++) $include[]=$s; elseif($id_from > $id_to) for ($s=$id_from; $s>=$id_to; $s--) $include[]=$s; } if (isset($postdata['include']) && !empty($postdata['include'])) { $postdata['include'] = array_merge($postdata['include'], $include); $postdata['include'] = array_flip(array_flip($postdata['include'])); } else { $postdata['include'] = $include; } if (!$postdata['force-scan']) { $exclude = get_option('qqworld-collector-remote-publish-refreshing-taxonomy-exclude-'.$guid, array()); $exclude = $exclude ? $exclude : array(); if (!empty($exclude)) $postdata['exclude'] = $exclude; } $postdata['hide_empty'] = true; $postdata['number'] = 100; for ($paged=0; $paged<1000; $paged++) { $postdata['offset'] = $postdata['number']*$paged; $terms = get_terms($postdata); if (!empty($terms)) { foreach ($terms as $term) { $this->publish_archive($args, $postdata['taxonomy'], $term); if (!$postdata['force-scan']) $exclude[] = $term->term_id; } if (!$postdata['force-scan']) { $exclude = array_flip(array_flip($exclude)); update_option('qqworld-collector-remote-publish-refreshing-taxonomy-exclude-'.$guid, $exclude); } } else { break; } } } public function do_publishing_homepage($args) { extract($args); if (!$this->client) $this->client = $this->get_client($args); $destination_path = '/index.html'; $content = file_get_contents(home_url()); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); } public function do_publishing_sitemap($args, $sitemap, $guid) { extract($args); extract($sitemap); if (!$this->client) $this->client = $this->get_client($args); $destination_path = '/'.$filename; $content = file_get_contents(home_url($filename)); $xml = simplexml_load_string($content); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); $record = get_option('qqworld-collector-remote-publish-refreshing-sitemap-record-'.$guid, array()); $array = json_decode(json_encode($xml, JSON_INVALID_UTF8_IGNORE), true); foreach ($array['sitemap'] as $sitemap) { extract($sitemap); if (isset($record[$loc]) && $record[$loc] == $lastmod) continue; $url_parser = parse_url($loc); $destination_path = $url_parser['path']; $content = file_get_contents($loc); $content = str_replace(home_url(), $host, $content); $this->handle($content, $destination_path); $record[$loc] = $lastmod; update_option('qqworld-collector-remote-publish-refreshing-sitemap-record-'.$guid, $record); } } } ?>